#[cfg(not(feature = "app"))]
pub(super) const TOP_LEVEL_HELP: &str = "gate\n\nUsage:\n  gate <COMMAND>\n  gate --help\n\nCommands:\n  pass      Advance a task by ID using the pipeline pass transition\n  reject    Reject a task by ID using the pipeline reject transition\n  append    Append agent notes to a task by ID\n  status    Report task state derived from disk\n  sync      Rebuild or reconcile the gate.db cache from disk\n\nNotes:\n  Markdown task files under todo/ and done/ are authoritative.\n  gate.db is a rebuildable cache/index only.\n";

#[cfg(feature = "app")]
pub(super) const TOP_LEVEL_HELP: &str = "gate\n\nUsage:\n  gate <COMMAND>\n  gate --mcp\n  gate --http [PORT]\n  gate --help\n\nCommands:\n  pass      Advance a task by ID using the pipeline pass transition\n  reject    Reject a task by ID using the pipeline reject transition\n  append    Append agent notes to a task by ID\n  status    Report task state derived from disk\n  sync      Rebuild or reconcile the gate.db cache from disk\n\nOptions:\n  --mcp         Run the gate MCP server over stdio\n  --http [PORT] Run the gate MCP server over streamable HTTP with a tray icon (default: 9879)\n\nNotes:\n  Markdown task files under todo/ and done/ are authoritative.\n  gate.db is a rebuildable cache/index only.\n";

pub(super) const PASS_HELP: &str = "gate-pass\n\nUsage:\n  gate pass [--db <DB>] [--root <ROOT>] [--notes <NOTES>] <ID>\n  gate pass --help\n\nArguments:\n  <ID>              Task ID to advance via the pipeline pass transition\n\nOptions:\n  --db <DB>         Path to the cache database (defaults to <ROOT>/gate.db)\n  --root <ROOT>     Pipeline root containing todo/ and done/ (defaults to current directory)\n  --notes <NOTES>   Notes to append to the orchestrator section\n";

pub(super) const REJECT_HELP: &str = "gate-reject\n\nUsage:\n  gate reject [--db <DB>] [--root <ROOT>] [--notes <NOTES>] <ID>\n  gate reject --help\n\nArguments:\n  <ID>              Task ID to reject via the pipeline reject transition\n\nOptions:\n  --db <DB>         Path to the cache database (defaults to <ROOT>/gate.db)\n  --root <ROOT>     Pipeline root containing todo/ and done/ (defaults to current directory)\n  --notes <NOTES>   Notes to append to the orchestrator section\n";

pub(super) const APPEND_HELP: &str = "gate-append\n\nUsage:\n  gate append [--db <DB>] [--root <ROOT>] --notes <NOTES> --agent <ROLE> <ID>\n  gate append --help\n\nArguments:\n  <ID>              Task ID to append notes to\n\nOptions:\n  --db <DB>         Path to the cache database (defaults to <ROOT>/gate.db)\n  --root <ROOT>     Pipeline root containing todo/ and done/ (defaults to current directory)\n  --notes <NOTES>   Required notes to append\n  --agent <ROLE>    Required agent role for the appended section heading\n";

pub(super) const STATUS_HELP: &str = "gate-status\n\nUsage:\n  gate status [--db <DB>] [--root <ROOT>] [--json] [ID]\n  gate status --help\n\nArguments:\n  [ID]         Optional task ID to inspect; omit to scan all tasks\n\nOptions:\n  --db <DB>      Path to the cache database used for drift checks and ID lookup\n  --root <ROOT>  Pipeline root containing todo/ and done/ (defaults to current directory)\n  --json         Emit JSON instead of human-readable text\n";

pub(super) const SYNC_HELP: &str = "gate-sync\n\nUsage:\n  gate sync [--db <DB>] [--rebuild] <ROOT>\n  gate sync --help\n\nArguments:\n  <ROOT>         Root containing authoritative todo/ and done/ task files\n\nOptions:\n  --db <DB>      Path to the cache database to rebuild/reconcile\n  --rebuild      Delete existing cached task/work log rows before inserting disk state\n";
